Here is the commit message:
ext4: fix partial cluster handling for bigalloc file systems

Commit 9cb00419fa, which enables hole punching for bigalloc file
systems, exposed a bug introduced by commit 6ae06ff51e in an earlier
release.  When run on a bigalloc file system, xfstests generic/013, 068,
075, 083, 091, 100, 112, 127, 263, 269, and 270 fail with e2fsck errors
or cause kernel error messages indicating that previously freed blocks
are being freed again.

The latter commit optimizes the selection of the starting extent in
ext4_ext_rm_leaf() when hole punching by beginning with the extent
supplied in the path argument rather than with the last extent in the
leaf node (as is still done when truncating).  However, the code in
rm_leaf that initially sets partial_cluster to track cluster sharing on
extent boundaries is only guaranteed to run if rm_leaf starts with the
last node in the leaf.  Consequently, partial_cluster is not correctly
initialized when hole punching, and a cluster on the boundary of a
punched region that should be retained may instead be deallocated.

Signed-off-by: Eric Whitney <enwlinux@gmail.com>
Signed-off-by: "Theodore Ts'o" <tytso@mit.edu>
Cc: stable@vger.kernel.org

Here is the root cause:
The bug was caused by an optimization in the `ext4_ext_rm_leaf` function that changed the starting extent selection to begin with the extent supplied in the path argument instead of the last extent in the leaf node. This change led to the `partial_cluster` variable not being correctly initialized when hole punching, resulting in the potential deallocation of clusters that should have been retained.

Here is the patch:
  */
 static int
 ext4_ext_rm_leaf(handle_t *handle, struct inode *inode,
 		 struct ext4_ext_path *path,
 		 long long *partial_cluster,
 		 ext4_lblk_t start, ext4_lblk_t end)
 {
 	struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
 	int err = 0, correct_index = 0;
 	int depth = ext_depth(inode), credits;
 	struct ext4_extent_header *eh;
 	ext4_lblk_t a, b;
 	unsigned num;
 	ext4_lblk_t ex_ee_block;
 	unsigned short ex_ee_len;
 	unsigned uninitialized = 0;
 	struct ext4_extent *ex;
 	ext4_fsblk_t pblk;

 	/* the header must be checked already in ext4_ext_remove_space() */
 	ext_debug("truncate since %u in leaf to %u\n", start, end);
 	if (!path[depth].p_hdr)
 		path[depth].p_hdr = ext_block_hdr(path[depth].p_bh);
 	eh = path[depth].p_hdr;
 	if (unlikely(path[depth].p_hdr == NULL)) {
 		EXT4_ERROR_INODE(inode, "path[%d].p_hdr == NULL", depth);
 		return -EIO;
 	}
 	/* find where to start removing */
 	ex = path[depth].p_ext;
 	if (!ex)
 		ex = EXT_LAST_EXTENT(eh);

 	ex_ee_block = le32_to_cpu(ex->ee_block);
 	ex_ee_len = ext4_ext_get_actual_len(ex);

+	/*
+	 * If we're starting with an extent other than the last one in the
+	 * node, we need to see if it shares a cluster with the extent to
+	 * the right (towards the end of the file). If its leftmost cluster
+	 * is this extent's rightmost cluster and it is not cluster aligned,
+	 * we'll mark it as a partial that is not to be deallocated.
+	 */
+
+	if (ex != EXT_LAST_EXTENT(eh)) {
+		ext4_fsblk_t current_pblk, right_pblk;
+		long long current_cluster, right_cluster;
+
+		current_pblk = ext4_ext_pblock(ex) + ex_ee_len - 1;
+		current_cluster = (long long)EXT4_B2C(sbi, current_pblk);
+		right_pblk = ext4_ext_pblock(ex + 1);
+		right_cluster = (long long)EXT4_B2C(sbi, right_pblk);
+		if (current_cluster == right_cluster &&
+			EXT4_PBLK_COFF(sbi, right_pblk))
+			*partial_cluster = -right_cluster;
+	}
+
 	trace_ext4_ext_rm_leaf(inode, start, ex, *partial_cluster);

 	while (ex >= EXT_FIRST_EXTENT(eh) &&
 			ex_ee_block + ex_ee_len > start) {

 		if (ext4_ext_is_uninitialized(ex))
 			uninitialized = 1;
 		else
 			uninitialized = 0;

 		ext_debug("remove ext %u:[%d]%d\n", ex_ee_block,
 			 uninitialized, ex_ee_len);
 		path[depth].p_ext = ex;

 		a = ex_ee_block > start ? ex_ee_block : start;
 		b = ex_ee_block+ex_ee_len - 1 < end ?
 			ex_ee_block+ex_ee_len - 1 : end;

 		ext_debug("  border %u:%u\n", a, b);

 		/* If this extent is beyond the end of the hole, skip it */
 		if (end < ex_ee_block) {
 			/*
 			 * We're going to skip this extent and move to another,
 			 * so if this extent is not cluster aligned we have
 			 * to mark the current cluster as used to avoid
 			 * accidentally freeing it later on
 			 */
 			pblk = ext4_ext_pblock(ex);
 			if (EXT4_PBLK_COFF(sbi, pblk))
 				*partial_cluster =
 					-((long long)EXT4_B2C(sbi, pblk));
 			ex--;
 			ex_ee_block = le32_to_cpu(ex->ee_block);
 			ex_ee_len = ext4_ext_get_actual_len(ex);
 			continue;
 		} else if (b != ex_ee_block + ex_ee_len - 1) {
 			EXT4_ERROR_INODE(inode,
 					 "can not handle truncate %u:%u "
 					 "on extent %u:%u",
 					 start, end, ex_ee_block,
 					 ex_ee_block + ex_ee_len - 1);
 			err = -EIO;
 			goto out;
 		} else if (a != ex_ee_block) {
 			/* remove tail of the extent */
 			num = a - ex_ee_block;
 		} else {
 			/* remove whole extent: excellent! */
 			num = 0;
 		}
 		/*
 		 * 3 for leaf, sb, and inode plus 2 (bmap and group
 		 * descriptor) for each block group; assume two block
 		 * groups plus ex_ee_len/blocks_per_block_group for
 		 * the worst case
 		 */
 		credits = 7 + 2*(ex_ee_len/EXT4_BLOCKS_PER_GROUP(inode->i_sb));
 		if (ex == EXT_FIRST_EXTENT(eh)) {
 			correct_index = 1;
 			credits += (ext_depth(inode)) + 1;
 		}
 		credits += EXT4_MAXQUOTAS_TRANS_BLOCKS(inode->i_sb);

 		err = ext4_ext_truncate_extend_restart(handle, inode, credits);
 		if (err)
 			goto out;

 		err = ext4_ext_get_access(handle, inode, path + depth);
 		if (err)
 			goto out;

 		err = ext4_remove_blocks(handle, inode, ex, partial_cluster,
 					 a, b);
 		if (err)
 			goto out;

 		if (num == 0)
 			/* this extent is removed; mark slot entirely unused */
 			ext4_ext_store_pblock(ex, 0);

 		ex->ee_len = cpu_to_le16(num);
 		/*
 		 * Do not mark uninitialized if all the blocks in the
 		 * extent have been removed.
 		 */
 		if (uninitialized && num)
 			ext4_ext_mark_uninitialized(ex);
 		/*
 		 * If the extent was completely released,
 		 * we need to remove it from the leaf
 		 */
 		if (num == 0) {
 			if (end != EXT_MAX_BLOCKS - 1) {
 				/*
 				 * For hole punching, we need to scoot all the
 				 * extents up when an extent is removed so that
 				 * we dont have blank extents in the middle
 				 */
 				memmove(ex, ex+1, (EXT_LAST_EXTENT(eh) - ex) *
 					sizeof(struct ext4_extent));

 				/* Now get rid of the one at the end */
 				memset(EXT_LAST_EXTENT(eh), 0,
 					sizeof(struct ext4_extent));
 			}
 			le16_add_cpu(&eh->eh_entries, -1);
 		} else if (*partial_cluster > 0)
 			*partial_cluster = 0;

 		err = ext4_ext_dirty(handle, inode, path + depth);
 		if (err)
 			goto out;

 		ext_debug("new extent: %u:%u:%llu\n", ex_ee_block, num,
 				ext4_ext_pblock(ex));
 		ex--;
 		ex_ee_block = le32_to_cpu(ex->ee_block);
 		ex_ee_len = ext4_ext_get_actual_len(ex);
 	}

 	if (correct_index && eh->eh_entries)
 		err = ext4_ext_correct_indexes(handle, inode, path);

 	/*
 	 * Free the partial cluster only if the current extent does not
 	 * reference it. Otherwise we might free used cluster.
 	 */
 	if (*partial_cluster > 0 &&
 	    (EXT4_B2C(sbi, ext4_ext_pblock(ex) + ex_ee_len - 1) !=
 	     *partial_cluster)) {
 		int flags = get_default_free_blocks_flags(inode);

 		ext4_free_blocks(handle, inode, NULL,
 				 EXT4_C2B(sbi, *partial_cluster),
 				 sbi->s_cluster_ratio, flags);
 		*partial_cluster = 0;
 	}

 	/* if this leaf is free, then we should
 	 * remove it from index block above */
 	if (err == 0 && eh->eh_entries == 0 && path[depth].p_bh != NULL)
 		err = ext4_ext_rm_idx(handle, inode, path, depth);

 out:
 	return err;
 }



